'use client'

import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react'
import { PHRASE_MAP, type LangCode, type Phrase } from './content'

export type Settings = {
  comfortLang: LangCode
  speakLangs: LangCode[]
  learningLang: LangCode
}

export type VocabEntry = {
  phraseId: string
  savedLabel: string
  mastery: number
  attempts: number
  misses: number
}

export type AppView = 'today' | 'vocabulary' | 'practice' | 'settings'

type Store = {
  hydrated: boolean
  onboarded: boolean
  completeOnboarding: (s: Settings) => void
  settings: Settings
  updateSettings: (s: Partial<Settings>) => void
  vocab: VocabEntry[]
  isSaved: (id: string) => boolean
  saveWord: (id: string) => void
  recordAnswer: (id: string, correct: boolean) => void
  weakest: (n?: number) => (VocabEntry & { phrase: Phrase })[]
  streak: number
  longestStreak: number
  appOpen: boolean
  openApp: (view?: AppView) => void
  closeApp: () => void
  appView: AppView
  setAppView: (v: AppView) => void
  dockPulse: number
  pulseDock: () => void
}

const StoreContext = createContext<Store | null>(null)

const SEED: VocabEntry[] = [
  { phraseId: 'dapjeongneo', savedLabel: 'Yesterday', mastery: 0.25, attempts: 4, misses: 3 },
  { phraseId: 'lowkey', savedLabel: '2 days ago', mastery: 0.45, attempts: 3, misses: 2 },
  { phraseId: 'eoieopda', savedLabel: '3 days ago', mastery: 0.7, attempts: 5, misses: 1 },
  { phraseId: 'seonbae', savedLabel: 'Last week', mastery: 0.9, attempts: 6, misses: 0 },
]

const STORAGE_KEY = 'lumen-state-v1'
const LANG_CODES = new Set<LangCode>(['en', 'ko', 'ja', 'es', 'zh', 'fr'])

function isLangCode(value: unknown): value is LangCode {
  return typeof value === 'string' && LANG_CODES.has(value as LangCode)
}

function readStoredState(): { onboarded: boolean; settings: Settings; vocab: VocabEntry[]; reviewDays: string[] } | null {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (!raw) return null
    const data: unknown = JSON.parse(raw)
    if (!data || typeof data !== 'object') return null
    const state = data as Record<string, unknown>
    const settings = state.settings as Record<string, unknown> | undefined
    if (!settings || !isLangCode(settings.comfortLang) || !isLangCode(settings.learningLang)) return null
    if (settings.comfortLang === settings.learningLang || !Array.isArray(settings.speakLangs)) return null
    const speakLangs = settings.speakLangs.filter(isLangCode)
    if (!Array.isArray(state.vocab)) return null
    const seen = new Set<string>()
    const vocab = state.vocab.filter((item): item is VocabEntry => {
      if (!item || typeof item !== 'object') return false
      const entry = item as Record<string, unknown>
      if (typeof entry.phraseId !== 'string' || !PHRASE_MAP[entry.phraseId] || seen.has(entry.phraseId)) return false
      if (typeof entry.savedLabel !== 'string' || typeof entry.mastery !== 'number' || !Number.isFinite(entry.mastery)) return false
      if (typeof entry.attempts !== 'number' || !Number.isInteger(entry.attempts) || entry.attempts < 0) return false
      if (typeof entry.misses !== 'number' || !Number.isInteger(entry.misses) || entry.misses < 0 || entry.misses > entry.attempts) return false
      seen.add(entry.phraseId)
      return true
    }).map((entry) => ({ ...entry, mastery: Math.max(0, Math.min(1, entry.mastery)) }))
    const reviewDays = Array.isArray(state.reviewDays)
      ? [...new Set(state.reviewDays.filter((day): day is string => typeof day === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(day)))].sort()
      : []
    return {
      onboarded: state.onboarded === true,
      settings: {
        comfortLang: settings.comfortLang,
        learningLang: settings.learningLang,
        speakLangs: [...new Set([settings.comfortLang, ...speakLangs])],
      },
      vocab,
      reviewDays,
    }
  } catch {
    return null
  }
}

function localDay(date: Date): string {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`
}

function streakStats(days: string[]): { streak: number; longestStreak: number } {
  const reviewed = new Set(days)
  const today = new Date()
  const cursor = new Date(today.getFullYear(), today.getMonth(), today.getDate())
  if (!reviewed.has(localDay(cursor))) cursor.setDate(cursor.getDate() - 1)
  let streak = 0
  while (reviewed.has(localDay(cursor))) {
    streak++
    cursor.setDate(cursor.getDate() - 1)
  }
  let longestStreak = 0
  let run = 0
  let previous: Date | null = null
  for (const day of days) {
    const current = new Date(`${day}T12:00:00`)
    if (Number.isNaN(current.getTime()) || localDay(current) !== day) continue
    if (previous) {
      const next = new Date(previous)
      next.setDate(next.getDate() + 1)
      run = localDay(next) === day ? run + 1 : 1
    } else run = 1
    longestStreak = Math.max(longestStreak, run)
    previous = current
  }
  return { streak, longestStreak }
}

export const weaknessScore = (v: VocabEntry) => (v.misses + 1) / (v.attempts + 2) + (1 - v.mastery)

export function StoreProvider({ children }: { children: React.ReactNode }) {
  const [hydrated, setHydrated] = useState(false)
  const [onboarded, setOnboarded] = useState(false)
  const [settings, setSettings] = useState<Settings>({ comfortLang: 'en', speakLangs: ['en'], learningLang: 'ko' })
  const [vocab, setVocab] = useState<VocabEntry[]>(SEED)
  const [reviewDays, setReviewDays] = useState<string[]>([])
  const [appOpen, setAppOpen] = useState(false)
  const [appView, setAppView] = useState<AppView>('today')
  const [dockPulse, setDockPulse] = useState(0)

  useEffect(() => {
    const stored = readStoredState()
    if (stored) {
      setOnboarded(stored.onboarded)
      setSettings(stored.settings)
      setVocab(stored.vocab)
      setReviewDays(stored.reviewDays)
    }
    setHydrated(true)
  }, [])

  useEffect(() => {
    if (!hydrated) return
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify({ onboarded, settings, vocab, reviewDays }))
    } catch {
      // The app remains usable when browser storage is unavailable.
    }
  }, [hydrated, onboarded, settings, vocab, reviewDays])

  const completeOnboarding = useCallback((s: Settings) => {
    setSettings(s)
    setOnboarded(true)
  }, [])

  const updateSettings = useCallback((s: Partial<Settings>) => setSettings((prev) => ({ ...prev, ...s })), [])

  const isSaved = useCallback((id: string) => vocab.some((v) => v.phraseId === id), [vocab])

  const saveWord = useCallback((id: string) => {
    setVocab((prev) =>
      prev.some((v) => v.phraseId === id)
        ? prev
        : [{ phraseId: id, savedLabel: new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }), mastery: 0, attempts: 0, misses: 0 }, ...prev],
    )
  }, [])

  const recordAnswer = useCallback((id: string, correct: boolean) => {
    setReviewDays((prev) => {
      const day = localDay(new Date())
      return prev.includes(day) ? prev : [...prev, day].sort()
    })
    setVocab((prev) =>
      prev.map((v) =>
        v.phraseId !== id
          ? v
          : {
              ...v,
              attempts: v.attempts + 1,
              misses: correct ? v.misses : v.misses + 1,
              mastery: Math.max(0, Math.min(1, v.mastery + (correct ? 0.15 : -0.1))),
            },
      ),
    )
  }, [])

  const { streak, longestStreak } = useMemo(() => streakStats(reviewDays), [reviewDays])

  const weakest = useCallback(
    (n = 3) =>
      [...vocab]
        .sort((a, b) => weaknessScore(b) - weaknessScore(a))
        .slice(0, n)
        .map((v) => ({ ...v, phrase: PHRASE_MAP[v.phraseId] })),
    [vocab],
  )

  const openApp = useCallback((view?: AppView) => {
    if (view) setAppView(view)
    setAppOpen(true)
  }, [])

  const value = useMemo<Store>(
    () => ({
      hydrated,
      onboarded,
      completeOnboarding,
      settings,
      updateSettings,
      vocab,
      isSaved,
      saveWord,
      recordAnswer,
      weakest,
      streak,
      longestStreak,
      appOpen,
      openApp,
      closeApp: () => setAppOpen(false),
      appView,
      setAppView,
      dockPulse,
      pulseDock: () => setDockPulse((p) => p + 1),
    }),
    [hydrated, onboarded, completeOnboarding, settings, updateSettings, vocab, isSaved, saveWord, recordAnswer, weakest, streak, longestStreak, appOpen, openApp, appView, dockPulse],
  )

  return <StoreContext.Provider value={value}>{children}</StoreContext.Provider>
}

export function useStore() {
  const ctx = useContext(StoreContext)
  if (!ctx) throw new Error('useStore must be used inside StoreProvider')
  return ctx
}
